/** `client.lending` — the lending methods of the TraceFast API. */
export class LendingApi {
  #http: Http

  constructor(http: Http) {
    this.#http = http
  }

  /**
   * The risk configuration of a lending protocol's markets.
   *
   * Plan: Intelligence or higher.
   *
   * The configuration of every asset of a lending protocol's markets (or of one, with `asset`), as its last configuration events set it (or its initialization did): loan-to-value, liquidation threshold, reserve factor and liquidation protocol fee (basis points), the liquidation bonus (basis points over the debt repaid: 500 = 5 %), supply and borrow caps (whole tokens; absent = no cap), whether the asset is active, frozen or paused, its price oracle, and the contracts of its receipt and debt tokens and its rate strategy. `coveredMarkets` names the markets TraceFast reads (Aave V3's main Ethereum market today); `protocol` must be one of them. A value is absent when the asset's initialization is not in the history TraceFast reads.
   *
   * @param protocol A covered protocol, for example `aave_v3`; another value is refused (`protocol_invalid`) with the covered list.
   * @param params Query parameters; a parameter left out is not sent.
   * @param options Per-call options: `signal`, `timeout`, `maxRetries`.
   * @throws {TraceFastError} on any failure — a subclass names the kind.
   * @see https://docs.tracefast.xyz/api/lending-config
   */
  async config(protocol: string, params?: LendingConfigParams, options?: RequestOptions): Promise<LendingConfigResponse> {
    return this.#http.get<LendingConfigResponse>(`/chains/${this.#http.chainId}/lending/${seg(protocol)}/config`, params, options)
  }
}

/** `client.network` — the network methods of the TraceFast API. */
